7	function electronMainCjsOutputPlugin(): Plugin {
8		return {
9			name: "recordly-electron-main-cjs-output",
10			enforce: "post",
11			config(config) {
12				// Vite mergeConfig concatenates lib.formats with the plugin's ESM default.
13				config.build ??= {};
14				const build = config.build;
15				const lib = build.lib;
16				if (lib && typeof lib === "object") {
17					lib.formats = ["cjs"];
18					lib.fileName = (_format, entryName) => `${entryName}.cjs`;
19				}
20	
21				build.rollupOptions ??= {};
22				const rollupOptions = build.rollupOptions;
23				const cjsOutput = {
24					format: "cjs" as const,
25					inlineDynamicImports: true,
26					entryFileNames: "[name].cjs",
27					chunkFileNames: "[name]-[hash].cjs",
28				};
29	
30				rollupOptions.output = Array.isArray(rollupOptions.output)
31					? rollupOptions.output.map((output) => ({ ...output, ...cjsOutput }))
32					: { ...(rollupOptions.output ?? {}), ...cjsOutput };
33			},
34		};
35	}
