37	function electronMainCjsGuardPlugin(): Plugin {
38		return {
39			name: "recordly-electron-main-cjs-guard",
40			closeBundle() {
41				const scriptPath = path.resolve(__dirname, "scripts/smoke-electron-main-cjs.mjs");
42				const result = spawnSync(process.execPath, [scriptPath], {
43					cwd: __dirname,
44					encoding: "utf8",
45				});
46	
47				if (result.status !== 0) {
48					const details = [result.stdout, result.stderr].filter(Boolean).join("\n");
49					throw new Error(
50						`Electron main CJS smoke failed after Vite build.${details ? `\n${details}` : ""}`,
51					);
52				}
53			},
54		};
55	}
