308	function createWindow() {
309		if (!app.isReady()) {
310			void app.whenReady().then(() => {
311				if (!mainWindow || mainWindow.isDestroyed()) {
312					createWindow();
313				}
314			});
315			return;
316		}
317	
318		if (isCreatingMainWindow) {
319			return;
320		}
321	
322		if (mainWindow && !mainWindow.isDestroyed()) {
323			restoreWindowSafely(mainWindow);
324			return;
325		}
326	
327		const existingHudWindow = getHudOverlayWindow();
328		if (existingHudWindow) {
329			mainWindow = existingHudWindow;
330			restoreWindowSafely(existingHudWindow);
331			return;
332		}
333	
334		isCreatingMainWindow = true;
335		const createdHudWindow = createHudOverlayWindow();
336		mainWindow = createdHudWindow;
337		createdHudWindow.once("closed", () => {
338			if (mainWindow === createdHudWindow) {
