345	function focusOrCreateMainWindow() {
346		if (!app.isReady()) {
347			void app.whenReady().then(() => {
348				focusOrCreateMainWindow();
349			});
350			return;
351		}
352	
353		const updateToast = getUpdateToastWindow();
354		if (updateToast?.isVisible()) {
355			updateToast.show();
356			updateToast.moveTop();
357			updateToast.focus();
358			return;
359		}
360	
361		if (!mainWindow || mainWindow.isDestroyed()) {
362			const existingHud = getHudOverlayWindow();
363			if (existingHud && !existingHud.isDestroyed()) {
364				mainWindow = existingHud;
365			} else {
366				createWindow();
367				return;
368			}
369		}
370	
371		if (mainWindow && !mainWindow.isDestroyed()) {
372			// On Linux/Wayland, focus() often doesn't take effect (compositor ignores it). Apps like Telegram
373			// work because they receive an XDG activation token via StatusNotifierItem.ProvideXdgActivationToken;
374			// Electron's tray doesn't handle that yet. Workaround: destroy and recreate the HUD so the new
375			// window gets focus (creation path works). Only for HUD, not editor.
376			if (
377				process.platform === "linux" &&
378				!mainWindow.isFocused() &&
379				!isEditorWindow(mainWindow)
380			) {
381				const win = mainWindow;
382				mainWindow = null;
383				win.once("closed", () => createWindow());
384				win.destroy();
385				return;
386			}
387	
388			// On Win32 with mouse passthrough enabled (Win11+), calling
389			// show/moveTop/focus on the transparent HUD overlay permanently corrupts
390			// setIgnoreMouseEvents forwarding, making it click-through.  Only focus
391			// the editor window; the HUD is alwaysOnTop so it doesn't need explicit
392			// focus.  On Win10 (passthrough disabled), the HUD is always interactive
393			// and can be safely shown/restored.
394			if (
395				process.platform === "win32" &&
396				!isEditorWindow(mainWindow) &&
397				isHudOverlayMousePassthroughSupported()
398			) {
399				showHudOverlayFromTray();
400				return;
401			}
402	
403			mainWindow.show();
404			if (mainWindow.isMinimized()) mainWindow.restore();
405			mainWindow.moveTop();
406			mainWindow.focus();
407		}
408	}
