753	function createEditorWindowWrapper() {
754		const existingEditorWindow = getExistingEditorWindow();
755		if (existingEditorWindow) {
756			mainWindow = existingEditorWindow;
757			restoreWindowSafely(existingEditorWindow);
758			return existingEditorWindow;
759		}
760	
761		if (isCreatingEditorWindow) {
762			const currentWindow = mainWindow;
763			if (currentWindow && !currentWindow.isDestroyed()) {
764				return currentWindow;
765			}
766	
767			const currentEditorWindow = getExistingEditorWindow();
768			if (currentEditorWindow) {
769				mainWindow = currentEditorWindow;
770				return currentEditorWindow;
771			}
772		}
773	
774		isCreatingEditorWindow = true;
775		const previousWindow = mainWindow;
776		if (previousWindow && !previousWindow.isDestroyed()) {
777			const closingEditorWindow = isEditorWindow(previousWindow);
778	
779			if (closingEditorWindow) {
780				closeEditorWindowBypassingUnsavedPrompt(previousWindow);
781			} else {
782				// It's the HUD or another window. Hide it instead of closing so background
783				// tasks (like webcam finalizing) can finish in its renderer process.
784				previousWindow.hide();
785			}
786	
787			if (!closingEditorWindow) {
788				isForceClosing = false;
789			}
790			if (mainWindow === previousWindow) {
791				mainWindow = null;
792			}
793		}
794		const editorWindow = createEditorWindow();
795		mainWindow = editorWindow;
796		editorHasUnsavedChanges = false;
797	
798		editorWindow.on("closed", () => {
799			if (mainWindow === editorWindow) {
800				mainWindow = null;
801			}
802			isCreatingEditorWindow = false;
803			isForceClosing = false;
804			editorHasUnsavedChanges = false;
805		});
806	
807		editorWindow.on("close", (event) => {
808			if (isForceClosing || !editorHasUnsavedChanges) {
809				if (process.platform === "win32" && !isForceClosing && !isAppQuitting) {
810					event.preventDefault();
811					closeEditorWindowToHud(editorWindow);
812				}
813				return;
814			}
815	
816			event.preventDefault();
817	
818			const choice = dialog.showMessageBoxSync(editorWindow, {
819				type: "warning",
820				buttons: ["Save & Close", "Discard & Close", "Cancel"],
821				defaultId: 0,
822				cancelId: 2,
823				title: "Unsaved Changes",
824				message: "You have unsaved changes.",
825				detail: "Do you want to save your project before closing?",
826			});
827	
828			if (choice === 0) {
829				editorWindow.webContents.send("request-save-before-close");
830				ipcMain.once("save-before-close-done", (_event, saved: boolean) => {
831					if (!saved) {
832						isAppQuitting = false;
833						return;
834					}
835	
836					if (process.platform === "win32" && !isAppQuitting) {
837						closeEditorWindowToHud(editorWindow);
838					} else {
839						closeEditorWindowBypassingUnsavedPrompt(editorWindow);
840					}
841				});
842			} else if (choice === 1) {
843				if (process.platform === "win32" && !isAppQuitting) {
844					closeEditorWindowToHud(editorWindow);
845				} else {
846					closeEditorWindowBypassingUnsavedPrompt(editorWindow);
847				}
848			} else {
849				isAppQuitting = false;
850			}
851		});
852	
853		return editorWindow;
854	}
