895	
896		session.defaultSession.setPermissionCheckHandler(
897			(webContents, permission, requestingOrigin, details) => {
898				return shouldGrantMediaPermission(
899					{
900						permission,
901						isTrustedCaptureWindow: isHudWebContents(webContents),
902						isMainFrame: details.isMainFrame,
903						currentDocumentUrl: webContents?.getURL() ?? "",
904						// Electron 39 may supply the last committed document URL, including its
905						// query, in the requestingOrigin argument for media checks.
906						requestingUrl: details.requestingUrl ?? requestingOrigin,
907						securityOrigins:
908							details.securityOrigin === undefined ? [] : [details.securityOrigin],
909					},
910					getTrustedCaptureDocumentBaseUrls(),
911				);
912			},
913		);
914	
915		session.defaultSession.setPermissionRequestHandler(
916			(webContents, permission, callback, details) => {
917				const securityOrigin = "securityOrigin" in details ? details.securityOrigin : undefined;
918	
919				callback(
920					shouldGrantMediaPermission(
921						{
922							permission,
923							isTrustedCaptureWindow: isHudWebContents(webContents),
924							isMainFrame: details.isMainFrame,
925							currentDocumentUrl: webContents.getURL(),
926							requestingUrl: details.requestingUrl,
927							securityOrigins: securityOrigin === undefined ? [] : [securityOrigin],
928						},
929						getTrustedCaptureDocumentBaseUrls(),
930					),
931				);
932			},
933		);
934	
935		// Recordly does not use WebHID, Web Serial, or WebUSB. Do not grant devices by default.
936		session.defaultSession.setDevicePermissionHandler(() => false);
937	
938		// macOS prompts for camera and microphone access at the point of use. Asking
939		// here blocks the first window behind two modal OS permission flows and makes
940		// a fresh install look hung. Windows has no equivalent request API, so retain
941		// its diagnostic warnings.
942		if (process.platform === "win32") {
943			const cameraStatus = systemPreferences.getMediaAccessStatus("camera");
944			const micStatus = systemPreferences.getMediaAccessStatus("microphone");
945			if (cameraStatus !== "granted") {
946				console.warn(
947					`[permissions] Camera access is "${cameraStatus}" — webcam may not work. Check Windows Settings > Privacy > Camera.`,
948				);
949			}
950			if (micStatus !== "granted") {
951				console.warn(
952					`[permissions] Microphone access is "${micStatus}" — mic recording may not work. Check Windows Settings > Privacy > Microphone.`,
953				);
954			}
955		}
956	
957		ipcMain.on("hud-overlay-close", () => {
958			const hud = getHudOverlayWindow();
959			if (hud) {
960				console.log("[main] Closing HUD window via hud-overlay-close");
961				hud.close();
962			}
963	
964			// If this was the last window (or we are in a state where we should quit), do it.
965			// We use a small delay to allow window.close() to propagate.
966			setTimeout(() => {
967				const windows = BrowserWindow.getAllWindows().filter((w) => !w.isDestroyed());
968				if (windows.length === 0) {
969					console.log("[main] No windows left, quitting app");
970					app.quit();
971				}
972			}, 100);
973		});
974		if (process.platform === "darwin" && app.dock) {
975			await app.dock.show();
976		}
977		syncDockIcon();
978		if (shouldUseTray()) {
979			createTray();
980			updateTrayMenu();
981		}
982		setupApplicationMenu();
983		await Promise.all([
984			ensureRecordingsDir(),
985			!VITE_DEV_SERVER_URL
986				? ensurePackagedRendererServer(RENDERER_DIST).catch((error) => {
987						console.warn(
988							"[renderer-server] Failed to start packaged renderer server:",
989							error,
990						);
991					})
992				: Promise.resolve(),
993			ensureMediaServer().catch((error) => {
994				console.warn("[media-server] Failed to start media server:", error);
995			}),
996		]);
997	
998		registerIpcHandlers(
999			createEditorWindowWrapper,
1000			createSourceSelectorWindowWrapper,
1001			() => mainWindow,
1002			() => sourceSelectorWindow,
1003			(recording: boolean, sourceName: string) => {
1004				selectedSourceName = sourceName;
1005				setHudOverlayRecordingActive(recording);
1006				if (shouldUseTray()) {
1007					if (!tray) createTray();
1008					updateTrayMenu(recording);
1009				}
1010				if (recording) {
1011					reassertHudOverlayMouseState();
1012				}
1013				if (!recording) {
1014					restoreWindowSafely(mainWindow);
1015				}
1016			},
1017		);
1018	
1019		if (IS_SMOKE_EXPORT || process.env.RECORDLY_DEV_OPEN_RECORDING_INPUT) {
1020			await logSmokeExportGpuDiagnostics();
1021			if (IS_SMOKE_EXPORT) {
1022				const smokeSource =
1023					process.env.RECORDLY_SMOKE_EXPORT_PROJECT ??
1024					process.env.RECORDLY_SMOKE_EXPORT_INPUT ??
1025					"<missing input>";
1026				console.log(`[smoke-export] Starting editor smoke export for ${smokeSource}`);
1027			} else {
1028				console.log(
1029					`[dev-open-recording] Starting editor for ${process.env.RECORDLY_DEV_OPEN_RECORDING_INPUT}`,
1030				);
1031			}
1032			createEditorWindowWrapper();
1033			return;
1034		}
1035	
1036		createWindow();
1037		setupAutoUpdates(getUpdateDialogWindow, sendUpdateToastToWindows);
1038		if (IS_DEV && process.env.RECORDLY_DEV_PREVIEW_UPDATE === "1") {
1039			setTimeout(() => {
1040				if (process.platform === "darwin") {
1041					previewUpdateToast(sendUpdateToastToWindows);
1042					return;
1043				}
1044	
1045				void previewNativeUpdateDialog(getUpdateDialogWindow);
1046			}, 750);
1047		}
1048	
1049		// Register the display media handler so that renderer's getDisplayMedia()
1050		// calls land on the pre-selected source without showing a system picker.
1051		//
1052		// IMPORTANT: The callback must receive a plain { id, name } Video object.
1053		// Passing the full DesktopCapturerSource (with thumbnail, appIcon, etc.)
1054		// via an unsafe cast breaks Electron's internal cursor-constraint
1055		// propagation and causes cursor: 'never' from the renderer to be silently
1056		// ignored by the native capture pipeline.
1057		session.defaultSession.setDisplayMediaRequestHandler(async (request, callback) => {
1058			try {
1059				const frame = request.frame;
1060				const isLiveFrame = Boolean(frame && !frame.isDestroyed());
1061				const requestingWebContents =
1062					isLiveFrame && frame ? electronWebContents.fromFrame(frame) : undefined;
1063				const isHudMainFrame = Boolean(
1064					isLiveFrame &&
1065						requestingWebContents &&
1066						isHudWebContents(requestingWebContents) &&
1067						frame === requestingWebContents.mainFrame,
1068				);
1069	
1070				if (
1071					!shouldGrantDisplayCapture(
1072						{
1073							isTrustedCaptureWindow: isHudMainFrame,
1074							isMainFrame: Boolean(isLiveFrame && frame?.parent === null),
1075							currentDocumentUrl: isLiveFrame ? (frame?.url ?? "") : "",
1076							securityOrigin: request.securityOrigin,
1077							videoRequested: request.videoRequested,
1078						},
1079						getTrustedCaptureDocumentBaseUrls(),
1080					)
1081				) {
1082					callback({});
1083					return;
1084				}
1085	
1086				// Browser and Linux portal capture starts as soon as this callback
1087				// resolves, before recording-state-changed is emitted.
1088				reassertHudOverlayCaptureProtection();
1089	
1090				const sourceId = getSelectedSourceId();
1091				// On Linux/Wayland, calling desktopCapturer.getSources() itself
1092				// invokes the xdg-desktop-portal picker. If we then return one of
1093				// those sources, Chromium triggers a SECOND portal because the
1094				// pre-enumerated source IDs are stale on Wayland. To collapse this
1095				// into a single portal invocation, when the Linux portal sentinel
1096				// is set we skip getSources entirely and hand back a synthetic
1097				// source id; Chromium then opens the portal once to actually
1098				// resolve the capture.
1099				// Default to the sentinel on Linux when no source has been
1100				// pre-selected (e.g. fresh session where the renderer skipped the
1101				// source picker entirely). This avoids calling getSources() which
1102				// would itself trigger an extra portal dialog.
1103				const isLinuxPortalSentinel =
1104					process.platform === "linux" && (sourceId === "screen:linux-portal" || !sourceId);
1105				if (isLinuxPortalSentinel) {
1106					callback({ video: { id: "screen:0:0", name: "Entire screen" } });
1107					return;
1108				}
1109				const sources = await desktopCapturer.getSources({ types: ["screen", "window"] });
1110				const source = sourceId
1111					? (sources.find((s) => s.id === sourceId) ?? sources[0])
1112					: sources[0];
1113				if (source) {
1114					callback({
1115						video: { id: source.id, name: source.name },
1116					});
1117				} else {
1118					callback({});
1119				}
1120			} catch (error) {
1121				console.error("setDisplayMediaRequestHandler error:", error);
1122				callback({});
1123			}
1124		});
1125	
1126		const currentToastPayload = getCurrentUpdateToastPayload();
1127		if (currentToastPayload) {
1128			sendUpdateToastToWindows("update-toast-state", currentToastPayload);
1129		}
1130	});
